import { useNavigate } from "react-router-dom";
// import "./Dashboard.css";

export default function Dashboard() {
  const navigate = useNavigate();

  const cards = [
    {
      title: "Upload & Analyze",
      desc: "Upload a contract and get summary, explanation, and risk score.",
      path: "/upload",
    },
    {
      title: "Ask a Question",
      desc: "Ask legal questions and get AI-assisted guidance.",
      path: "/qa",
    },
    {
      title: "Contract Templates",
      desc: "Browse ready-made templates and filter by category.",
      path: "/templates",
    },
    {
      title: "Find a Lawyer",
      desc: "Search lawyers by city and specialty.",
      path: "/lawyers",
    },
  ];

  return (
    <div className="dash-bg">
      <div className="dash-container">
        <div className="dash-header">
          <h1>Digital Legal Advisor</h1>
          <p>Your hub for understanding legal documents in plain language.</p>
        </div>

        <div className="dash-grid">
          {cards.map((c) => (
            <button
              key={c.title}
              className="dash-card"
              onClick={() => navigate(c.path)}
            >
              <h3>{c.title}</h3>
              <p>{c.desc}</p>
              <span className="dash-link">Open →</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
